import fs from 'node:fs';import path from 'node:path';import cp from 'node:child_process';import {syncBuiltinESMExports} from 'node:module';import {pathToFileURL} from 'node:url';
const repo=process.cwd();const parent=path.resolve(repo,'.tmp');fs.mkdirSync(parent,{recursive:true});const owned=fs.mkdtempSync(path.join(parent,'cons03-delta-'));const ownedReal=fs.realpathSync(owned);const output={};const originalSpawn=cp.spawnSync;const originalKill=process.kill;
try{const mod=await import(pathToFileURL(path.join(repo,'scripts/verify-cf05-ui-live.mjs')).href);
for(const id of ['../escaped','invalid/id:with*chars']){try{mod.validateAndReserveEvidenceDir(id,owned,true);output[id]='ALLOWED'}catch(e){output[id]=e.message}}
const first=mod.validateAndReserveEvidenceDir('unique',owned,true);const mf=path.join(first.runEvidenceDir,'manifest.json');fs.writeFileSync(mf,'SENTINEL');try{mod.validateAndReserveEvidenceDir('unique',owned,true);output.duplicate='ALLOWED'}catch(e){output.duplicate=e.message}output.sentinelPreserved=fs.readFileSync(mf,'utf8')==='SENTINEL';
// Reproduce precisely the directory precreation performed by the wrapper; do not invoke PowerShell/secrets.
fs.mkdirSync(path.join(owned,'docs/audit/evidence/runs/wrapper-id/screenshots'),{recursive:true});try{mod.validateAndReserveEvidenceDir('wrapper-id',owned,false);output.wrapperPrecreated='ALLOWED'}catch(e){output.wrapperPrecreated=e.message}
// Intercept ALL kill operations in the disposable Node process. Never call taskkill.
const attempted=[];cp.spawnSync=(cmd,args,opts)=>{attempted.push({cmd,args});return {status:1,stdout:'',stderr:'synthetic denied termination'}};syncBuiltinESMExports();process.kill=()=>{const e=new Error('synthetic liveness denied');e.code='EPERM';throw e;};
const instance=new mod.ChromeInstance(0,'unit');instance.profileDir=path.join(owned,'profile-not-created');instance.proc={pid:process.pid};try{await instance.stop();output.firstStop='PASS'}catch(e){output.firstStop=e.message}output.retainsProcessAfterFailure=!!instance.proc;try{await instance.stop();output.secondStop='PASS'}catch(e){output.secondStop=e.message}output.selfTermination={attempted,ownPid:process.pid,realKillExecuted:false};
}finally{cp.spawnSync=originalSpawn;syncBuiltinESMExports();process.kill=originalKill;if(fs.realpathSync(owned)!==ownedReal||path.dirname(ownedReal)!==fs.realpathSync(parent)||!path.basename(ownedReal).startsWith('cons03-delta-'))throw new Error('Cleanup path boundary failed');fs.rmSync(ownedReal,{recursive:true,force:true});output.sandboxRemoved=!fs.existsSync(ownedReal)}
console.log(JSON.stringify(output,null,2));

